CREATE OR REPLACE FUNCTION public.crm_catalog_reorder(_data jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a crm_catalogs; b crm_catalogs; first_id uuid:=(_data->>'id')::uuid; second_id uuid:=(_data->>'other_id')::uuid; BEGIN IF NOT crm_can(auth.uid(),'biz.crm_settings') THEN RAISE EXCEPTION 'Bạn không có quyền cài đặt CRM.'; END IF; PERFORM pg_advisory_xact_lock(hashtext('crm_catalogs')); SELECT * INTO a FROM crm_catalogs WHERE id=first_id FOR UPDATE; SELECT * INTO b FROM crm_catalogs WHERE id=second_id FOR UPDATE; IF a.id IS NULL OR b.id IS NULL OR a.id=b.id OR a.kind<>b.kind OR a.parent_id IS DISTINCT FROM b.parent_id THEN RAISE EXCEPTION 'Chỉ sắp xếp các danh mục cùng nhóm.'; END IF; UPDATE crm_catalogs SET sort_order=CASE WHEN id=a.id THEN b.sort_order ELSE CASE WHEN a.sort_order=b.sort_order THEN a.sort_order+CASE WHEN coalesce((_data->>'direction')::int,1)>0 THEN -1 ELSE 1 END ELSE a.sort_order END END WHERE id IN (a.id,b.id); INSERT INTO crm_events(actor_id,action,before_data,after_data) VALUES(auth.uid(),'catalog_reorder',jsonb_build_array(to_jsonb(a),to_jsonb(b)),(SELECT jsonb_agg(to_jsonb(c)) FROM crm_catalogs c WHERE id IN (a.id,b.id))); END $$;
REVOKE ALL ON FUNCTION public.crm_catalog_reorder(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.crm_catalog_reorder(jsonb) TO authenticated,service_role;
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_catalog_save(jsonb)'::regprocedure) INTO d; d:=replace(d,'WHERE id=p AND active AND kind=ANY','WHERE id=p AND (active OR old->>''parent_id''=p::text) AND kind=ANY'); EXECUTE d; SELECT pg_get_functiondef('public.crm_report_filtered(date,date,boolean,uuid,uuid,text,uuid,uuid,uuid,uuid,uuid,uuid,boolean)'::regprocedure) INTO d; d:=replace(d,'SELECT coalesce(jsonb_agg(x),''[]'') INTO cs','SELECT coalesce(jsonb_agg(x || jsonb_build_object(''last_care_at'',(SELECT max(i.happened_at) FROM crm_interactions i WHERE i.customer_id=(x->>''id'')::uuid AND i.completed AND i.happened_at<hi AND crm_owner_visible(i.owner_id,i.department_id,i.happened_at) AND (NOT _mine OR i.owner_id=auth.uid()) AND (_owner IS NULL OR i.owner_id=_owner)))),''[]'') INTO cs'); EXECUTE d; END $$;